  function progressReportHtml(d){const months=['','OCAK','ŞUBAT','MART','NİSAN','MAYIS','HAZİRAN','TEMMUZ','AĞUSTOS','EYLÜL','EKİM','KASIM','ARALIK'],month=months[Number(d.ay)]||'',total=Number(d.sozlesme_fiyatlariyla_hizmet||0)+Number(d.fiyat_farki||0);return`<div class="classic-progress-report"><table><tbody><tr><th colspan="4" class="report-title">HAKEDİŞ RAPORU</th></tr><tr><th colspan="3" class="report-subtitle">PERSONEL HİZMETİ ALIMI TEMİZLİK İŞLERİ MÜDÜRLÜĞÜ ${month} ${esc(d.yil)}</th><td class="report-no">Hakediş No : ${esc(d.hak_edis_no)}</td></tr><tr><td colspan="4" class="report-date">${reportDate(d.rapor_tarihi)} TARİHİNE KADAR YAPILAN HİZMETİN</td></tr><tr class="gap"><td colspan="4"></td></tr>${reportLine('A','Sözleşme Fiyatları İle Yapılan Hizmet Tutarı',reportNumber(d.sozlesme_fiyatlariyla_hizmet))}${reportLine('B','Fiyat Farkı Tutarı',reportNumber(d.fiyat_farki))}${reportLine('C','Toplam Tutar ( A + B )',reportNumber(total),'strong')}<tr class="gap"><td colspan="4"></td></tr>${reportLine('D','Bir Önceki Hakedişin Toplam Tutarı',reportNumber(d.onceki_hakedis_toplami))}${reportLine('E','Bu Hakedişin Tutarı ( C - D )',reportNumber(d.bu_hakedis_tutari))}${reportLine('F','KDV ( E x %1 )',reportNumber(d.kdv_tutari))}${reportLine('G','Tahakkuk Tutarı',reportNumber(d.tahakkuk_tutari),'strong')}<tr><th rowspan="10" colspan="2" class="deduction-title">KESİNTİLER VE MAHSUPLAR</th><td>a) Sözleşmeye Ait Damga Vergisi ( E x % ... )</td><td>${reportNumber(0)}</td></tr>${deductionLine('b) Ödemeye Ait Damga Vergisi',reportNumber(d.damga_vergisi))}${deductionLine('c) KDV Tevkifatı ( F x ... )',reportNumber(0))}${deductionLine('d) Sosyal Sigortalar Kurumu Kesintisi','-----')}${deductionLine('e) İdare Makinesi Kiraları','-----')}${deductionLine('f) Gecikme Cezası','-----')}${deductionLine('g) Avans Mahsubu','-----')}${deductionLine('h) Bu Hakedişle Ödenen Fiyat Farkı<br>&nbsp;&nbsp;&nbsp;Teminat Kesintisi','-----')}${deductionLine('........................','')}${deductionLine('…………………..','')}${reportLine('H','Kesintiler ve Mahsuplar Toplamı',reportNumber(d.kesinti_toplami),'strong')}${reportLine('','Yükleniciye Ödenecek Tutar ( G - H )',reportNumber(d.odenecek_tutar),'strong')}<tr class="signature-divider"><td colspan="4"></td></tr><tr class="signatures"><td colspan="2">YÜKLENİCİ</td><td colspan="2">D Ü Z E N L E Y E N L E R<br><small>(Yetkili Kontrol Elemanları)</small><div class="approval">....../...../......<br>ONAYLAYAN</div></td></tr></tbody></table></div>`}
